import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"AI Slop과 인지 피로","description":"AI가 만드는 어색한 문장과 인지 피로(브레인 프라이)","frontmatter":{"title":"AI Slop과 인지 피로","date":"2026-08-09T18:00+09:00","description":"AI가 만드는 어색한 문장과 인지 피로(브레인 프라이)","tags":["AI","Slop","인지 피로","브레인 프라이"]},"headers":[],"relativePath":"posts/ai-slop.md","filePath":"posts/ai-slop.md","lastUpdated":1787309558000}`),a={name:`posts/ai-slop.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="ai-slop과-인지-피로" tabindex="-1">AI Slop과 인지 피로 <a class="header-anchor" href="#ai-slop과-인지-피로" aria-label="Permalink to “AI Slop과 인지 피로”">​</a></h1><p><a href="https://www.youtube.com/watch?v=_zfN9wnPvU0" target="_blank" rel="noreferrer">AI 슬롭이 인터넷을 망가트리고 있습니다.</a> AI 슬롭(Slop)은 단순히 화면 디자인으로만 만들어지지 않아요.</p><p>최근 AI 에이전트를 업무에 활용하게 되면서 이슈 내용과 메시지를 대신 작성하도록 요청하고 있습니다. 그러다보니 AI 가 만들어낸 이슈와 메시지에서 어색한 문장으로 인해 동료들이 피로감을 느끼고 있습니다. 그래서 메시지 채널을 이용하고 있음에도 불구하고 일부 동료들은 직접 찾아와서 구두로 상황을 설명해달라고 요청하고 있습니다.</p><h2 id="ai-에이전트가-만드는-피로" tabindex="-1">AI 에이전트가 만드는 피로 <a class="header-anchor" href="#ai-에이전트가-만드는-피로" aria-label="Permalink to “AI 에이전트가 만드는 피로”">​</a></h2><p>사실은 현재 이슈에 들어갈 내용이나 메시지를 AI 에이전트가 알아서 등록하진 않습니다. 현재 진행중이거나 완료된 부분에 대해서 메시지나 댓글 생성을 요청한 저도 AI 에이전트가 만들어서 제시한 초안을 보면 이해하기 어려운 경우가 많기 때문에 (반 자동화 관점으로) 에이전트가 초안을 만들고게 한 후에 여러번 다듬은 결과를 보고 승인하고 있습니다.</p><p>그럼에도 불구하고, 이슈와 메시지를 본 동료들은 배경과 이슈에 대한 맥락을 알기 어렵기 때문에 한눈에 핵심을 파악하기란 어렵다고 느낍니다. 이슈 내용과 메시지를 이해하려면 상세하게 읽어야만 파악할 수 있기 때문에 이 과정에 대한 스트레스가 과도해지고 있는 것 같습니다.</p><p>또한, 현재 조직은 문서화를 만들어서 일하던 스타일이 아니었기 때문에 프로젝트 코드를 분석해서 AI 가 정리해준 문서를 막상 읽어보면 무슨 말을 하는 지 파악하기 정말 어렵습니다. AI는 분석 과정과 파악된 사실을 최대한 서술하고, 코드를 추상적인 문장으로 상세히 적어 두지만, 정작 핵심 동작과 작성 목적은 과도한 기술 용어에 가려져 보이지 않습니다. 결국 이 문서들은 사람이 아닌 AI 에이전트만 이해할 수 있는 사람에게는 의미 없는 문서가 만들어질 뿐입니다.</p><h2 id="브레인-프라이-ai로-인한-인지-피로와-부작용" tabindex="-1">브레인 프라이: AI로 인한 인지 피로와 부작용 <a class="header-anchor" href="#브레인-프라이-ai로-인한-인지-피로와-부작용" aria-label="Permalink to “브레인 프라이: AI로 인한 인지 피로와 부작용”">​</a></h2><p>인터넷에서는 이러한 인지 피로가 누적되는 상황을 <strong>브레인 프라이 (Brain Fried)</strong> 라고 말합니다. AI가 생성한 결과물(AI Slop)을 이해하고 검증하려 할 때 받는 인지적 스트레스를 의미하죠.</p><ul><li><a href="https://www.jobkorea.co.kr/goodjob/tip/view?News_No=22569" target="_blank" rel="noreferrer">AI가 다 해준다더니, 더 바빠진 AI 번아웃의 현실</a></li><li><a href="https://yozm.wishket.com/magazine/detail/3845/" target="_blank" rel="noreferrer">AI 답변 복붙이 우리 팀을 피곤하게 만드는 이유</a></li><li><a href="https://news.hada.io/topic?id=26520" target="_blank" rel="noreferrer">AI 피로는 실제로 존재하지만 아무도 이야기하지 않는다</a></li></ul><p>위 링크들에서 말하는 <mark>AI 피로와 번아웃</mark>은 에이전트가 작업 세션에서 다룬 모든 탐색 과정을 글에 담으려다 보니 발생합니다. 사람은 상대방이 쉽게 이해하도록 핵심 내용만 필터링해서 전달하려는 경향이 있지만, AI 에이전트는 탐색 중에 발견한 특이점까지 모조리 설명하려 듭니다.</p><h3 id="_1-업무-집중도-하락과-컨텍스트-스위칭" tabindex="-1">1. 업무 집중도 하락과 컨텍스트 스위칭 <a class="header-anchor" href="#_1-업무-집중도-하락과-컨텍스트-스위칭" aria-label="Permalink to “1. 업무 집중도 하락과 컨텍스트 스위칭”">​</a></h3><p>최근 실무에서는 AI 에이전트가 직접 CLI를 사용해 깃허브 이슈와 댓글을 등록하고, 의견 확인이 필요한 순간마다 구글 스페이스로 메시지를 보냅니다. 잦은 알림과 호출로 인해 의사결정권자들의 멘션 스트레스가 늘어납니다.</p><p>실무자는 직접 검수한 결과물이라 맥락을 어느 정도 이해하지만, 전달받는 사람은 AI 메시지 내용이 한눈에 들어오지 않아 여러 번 정독해야 합니다. 결국 메시지를 이해하려고 진행 중이던 업무에서 벗어나는 <mark>컨텍스트 스위칭</mark>이 자주 일어납니다.</p><h3 id="_2-금방-잊히는-변경사항과-검증의-한계" tabindex="-1">2. 금방 잊히는 변경사항과 검증의 한계 <a class="header-anchor" href="#_2-금방-잊히는-변경사항과-검증의-한계" aria-label="Permalink to “2. 금방 잊히는 변경사항과 검증의 한계”">​</a></h3><p>제품 변경을 인지하기 어려운 큰 이유는 직접 확인했던 내용조차 금방 잊어버리기 때문입니다. 내가 고민해서 작성한 코드가 아니다 보니 머릿속에 남는 히스토리가 적습니다.</p><p>또한 백엔드 개발자가 AI 에이전트의 도움으로 프론트엔드 코드까지 다루는 등 작업 범위가 넓어지면서 인지 부하가 더욱 커집니다. 익숙하지 않은 영역이다 보니 AI가 작성한 결과물을 완벽히 검증하기 어렵습니다. 결국 리뷰를 요청하는 사람조차 내용을 완전히 이해하지 못한 채 상급자나 다른 담당자에게 리뷰를 요청하는 악순환이 생깁니다.</p><h2 id="ai-가-만들어내는-slop-메시지" tabindex="-1">AI 가 만들어내는 Slop 메시지 <a class="header-anchor" href="#ai-가-만들어내는-slop-메시지" aria-label="Permalink to “AI 가 만들어내는 Slop 메시지”">​</a></h2><p>일부 공개 저장소를 살펴보면 AI 가 만들어내는 Slop 메시지를 쉽게 볼 수 있습니다. 대표적으로 <a href="https://github.com/modu-ai/cowork-plugins" target="_blank" rel="noreferrer">cowork-plugins</a> 또는 <a href="https://github.com/epoko77-ai/im-not-ai" target="_blank" rel="noreferrer">im-not-ai</a> 저장소를 보시면 됩니다.</p><ul><li>Claude Code — 플러그인 마켓플레이스</li><li>왜 한글 특화인가</li><li>빠르고 싸게 끝납니다.</li><li>절감은 모델 교체가 아니라 콜 수 축소에서 옵니다</li><li>v2.1에서 은퇴했습니다</li></ul><p>AI 티를 제거하는 것을 목표로하는 스킬 저장소 조차도 난해하고 장황하게 설명되는 메시지로 생성된 형태 그대로 사용하는 걸 보여줍니다. 이러한 메시지들을 자주보게 되면 인지 피로가 누적되면서 최근엔 <a href="https://news.hada.io/topic?id=31286" target="_blank" rel="noreferrer">AI 번아웃을 호소하는 이들</a>이 많아지는 상황이 만들어지는 거죠.</p><h2 id="ai가-매끄러운-문장을-만들도록-유도" tabindex="-1">AI가 매끄러운 문장을 만들도록 유도 <a class="header-anchor" href="#ai가-매끄러운-문장을-만들도록-유도" aria-label="Permalink to “AI가 매끄러운 문장을 만들도록 유도”">​</a></h2><p>&quot;글을 매끄럽게 다듬어주는 워크플로우나 스킬을 직접 만드세요.&quot;</p><p><a href="https://github.com/hardikpandya/stop-slop/blob/main/SKILL.md" target="_blank" rel="noreferrer">Stop Slop</a> 과 같은 저장소들의 윤문(문장을 매끄럽게 다듬어주는) 스킬들은 단순히 가독성을 목표로 하는게 아니라 무생물 주어, 피동태, 외래어 남용, 번역투를 발견해서 자연스러운 형태로 교정하는 것을 목표로 합니다.</p><p>결국 AI를 사용해서 가독성이 있는 메시지를 만들게 하려면 너무 짧은 문장을 반복하거나, 문장들의 줄 간격을 짧게 구성하게 하면 안된다고 윤문화 스킬들이 말해주고 있죠. 메시지의 행 간격이 너무 좁게 느껴지지 않게 하려면 적절한 여백을 넣도록 규칙을 남겨서 가이드 해야합니다.</p><h3 id="과정대로-서술하면-장황해진다" tabindex="-1">과정대로 서술하면 장황해진다 <a class="header-anchor" href="#과정대로-서술하면-장황해진다" aria-label="Permalink to “과정대로 서술하면 장황해진다”">​</a></h3><p>사람은 요약에 익숙하지만 AI는 과정을 충실히 설명하려고 합니다. 핵심과 결론 뿐만 아니라 모든 탐색 과정에서 발견된 정보와 결정들을 부연 설명으로 포함하려는 경향이 있죠. 결국 의식의 흐름대로 서술하면 장황해져서 가독성이 부족한 결과가 됩니다.</p><ul><li>무엇을 말하는가</li><li>문제는 A 가 아니라 B 에 있습니다.</li><li>X 가 발화하고, Y 가 유지되어집니다.</li><li>중요한 발견입니다, 이것이 바로 그 이유입니다.</li></ul><h3 id="답답하게-느껴지는-문장의-호흡" tabindex="-1">답답하게 느껴지는 문장의 호흡 <a class="header-anchor" href="#답답하게-느껴지는-문장의-호흡" aria-label="Permalink to “답답하게 느껴지는 문장의 호흡”">​</a></h3><p>가독성 있게 글쓰는 노하우를 찾아보면 문장을 짧게 만들라고 말합니다. 그러나 AI 에이전트가 만드는 메시지에서는 너무 짧은 문장들이 많이 보이죠. 오히려 답답하게 느껴지게 만들어버리는 원인이 되어버립니다.</p><ul><li>너무 짧은 호흡으로 줄바꿈 없이 나열</li><li>제목이나 목록으로 나누고 대시(ㅡ) 로 설명을 연결</li></ul><h3 id="번역된-문장의-느낌을-주는-구성" tabindex="-1">번역된 문장의 느낌을 주는 구성 <a class="header-anchor" href="#번역된-문장의-느낌을-주는-구성" aria-label="Permalink to “번역된 문장의 느낌을 주는 구성”">​</a></h3><p>AI 가 만들어준 메시지 초안이 가독성이 떨어지는 번역투를 가지게 되는 이유는 다음과 같습니다.</p><ul><li>직역된 외래어 남용(스테일, 게이트, 창 등)</li><li>지나치게 과도하게 사용되는 이모지</li><li>영어식 표현(무생물 주어와 피동형 문장)</li></ul><p>감사합니다.</p>`,35)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};